const fs=require('node:fs'),os=require('node:os'),path=require('node:path'),request=require('supertest');
const {createAuthenticatedActionApp}=require('./authenticated-app.cjs');
const {FORMAT}=require('./action-state.cjs');
const {loadCatalog}=require('./knowledge-catalog.cjs');
const {commitTransaction,atomicJson}=require('../../../storage-transaction');
let directory,app,alice,bob,owner,revision,state,practice,fail;
function options(){return {dataDir:directory,reviewDirectory:path.join(directory,'assets'),rateLimitEnabled:false,eventDeletionCommit:(dir,entries)=>commitTransaction(dir,entries,(file,value)=>{if(fail&&file.endsWith('records.json')){fail=false;throw Error('Fixture deletion interrupted')}atomicJson(file,value)})}}
async function save(agent,data){const old=(await agent.get('/api/action-state')).body;const r=await agent.put('/api/action-state').set('If-Match',old.revision).send({format:FORMAT,data});expect(r.status).toBe(200);return r.body.revision}
async function remove(eventId='parent',rev=revision,agent=alice,confirmed=true){return agent.post('/api/review-event-deletion').set('If-Match','"'+rev+'"').send({eventId,confirmed})}
beforeEach(async()=>{directory=fs.mkdtempSync(path.join(os.tmpdir(),'dianliang-delete-event-'));fail=false;app=createAuthenticatedActionApp(options()).app;alice=request.agent(app);bob=request.agent(app);owner=(await alice.post('/api/register').send({name:'deletion-alice',password:'test-only-2026'})).body.user.id;await bob.post('/api/register').send({name:'deletion-bob',password:'test-only-2026'});const n={...loadCatalog().nodes.find(n=>n.originId==='eq'),id:'eq',version:1,methods:[]},event=(id,start,end)=>({id,name:id,startedAt:start,endedAt:end,segments:[{start,end}],notes:[],steps:[],stepDone:{},draft:''}),parent={...event('parent',0,1000),notes:[{id:'note',text:'PRIVATE-PARENT-NOTE',at:0}],knowledge:{nodeId:'eq',nodeTitle:n.title,nodeGoal:n.goal,nodeVersion:1,nodeDomain:n.domain,nodeBranch:n.branch,nodeOwnership:n.ownership,nodeVisibility:n.visibility,methodId:null,methodTitle:'独立尝试',version:null,content:'',resource:'',five:n.five}};state={schema:1,mode:'local-simulation',activeId:'child',habitId:'h',habits:[{id:'h',name:'阅读',formedAt:null}],templates:{},nodes:[n],events:[parent,{...event('child',1000,null),parentId:'parent',parentStepId:'step'},{...event('grand',1000,1000),parentId:'child'}],lights:[{id:'light',eventId:'parent',nodeId:'eq',confirmed:false,public:false,result:'',evidence:''}]};revision=await save(alice,state);practice=(await alice.post('/api/review-practices').set('If-Match',revision).send({eventId:'parent',practiceMode:'independent',tutorialId:null,tutorialVersion:null,visibility:'private'})).body.record;expect(practice.id).toBeTruthy()});
afterEach(()=>{if(!path.resolve(directory).startsWith(path.resolve(os.tmpdir())+path.sep))throw Error('Unexpected fixture');fs.rmSync(directory,{recursive:true,force:true})});
it('deletes the event and owned service copies atomically while keeping the active child and descendants',async()=>{const r=await remove();expect(r.status).toBe(200);const after=(await alice.get('/api/action-state')).body;expect(after.revision).toBe(r.body.revision);expect(after.state.data.events.map(e=>e.id)).toEqual(['child','grand']);expect(after.state.data.activeId).toBe('child');expect(after.state.data.events[0].segments).toEqual(state.events[1].segments);expect(after.state.data.events[0].parentOrigin).toMatchObject({id:'parent',name:'parent',stepId:'step'});expect(JSON.stringify(after.state.data.events[0].parentOrigin)).not.toContain('PRIVATE-PARENT-NOTE');expect(after.state.data.events[1].parentId).toBe('child');expect(after.state.data.lights).toEqual([]);expect((await alice.get('/api/records')).body.records).toEqual([]);expect((await alice.get('/api/review-practices')).body.receipts).toEqual([]);expect((await remove()).body.repeated).toBe(true)});
it('does not delete another account practice that happens to use the same event ID',async()=>{const other={...structuredClone(state),activeId:null,events:[structuredClone(state.events[0])]},rev=await save(bob,other);const theirs=(await bob.post('/api/review-practices').set('If-Match',rev).send({eventId:'parent',practiceMode:'independent',tutorialId:null,tutorialVersion:null,visibility:'private'})).body.record;expect((await remove()).status).toBe(200);expect((await bob.get('/api/records')).body.records.map(r=>r.id)).toEqual([theirs.id]);expect((await bob.get('/api/action-state')).body.state.data.events).toHaveLength(1)});
it('rejects unfinished events, missing confirmation, stale revisions and another actor without changing files',async()=>{const file=path.join(directory,'action-states',owner+'.json'),before=fs.readFileSync(file,'utf8');expect((await remove('child')).status).toBe(400);expect((await remove('parent',revision,alice,false)).status).toBe(400);expect((await remove('parent','stale')).status).toBe(409);expect((await alice.post('/api/review-event-deletion').set('X-Action-Account','someone-else').set('If-Match',revision).send({eventId:'parent',confirmed:true})).status).toBe(409);expect(fs.readFileSync(file,'utf8')).toBe(before)});
it('recovers an interrupted multi-file deletion and confirms a retry without restoring deleted content',async()=>{fail=true;const r=await remove();expect(r.status).toBe(500);expect(r.body.code).toBe('EVENT_DELETION_COMMIT_UNCONFIRMED');expect(fs.existsSync(path.join(directory,'restore-journal.json'))).toBe(true);expect((await alice.get('/api/action-state')).body.state.data.events.some(e=>e.id==='parent')).toBe(false);expect((await alice.get('/api/records')).body.records).toEqual([]);expect((await alice.get('/api/review-practices')).body.receipts).toEqual([]);expect((await remove()).body.repeated).toBe(true);expect(fs.existsSync(path.join(directory,'restore-journal.json'))).toBe(false)});
